create extension if not exists pgcrypto;
create type app_role as enum ('admin','seller');
create type ticket_state as enum ('available','reserved','paid','blocked');
create type order_state as enum ('reserved','partial','proof_pending','paid','expired','cancelled');
create type payment_state as enum ('pending','approved','rejected');
create table profiles(id uuid primary key references auth.users(id), role app_role not null default 'seller',active boolean not null default true, created_at timestamptz not null default now());
create table raffles(id uuid primary key default gen_random_uuid(),name text not null,prize text not null,price_cents integer not null check(price_cents>0),draw_at timestamptz,payment_deadline timestamptz,reservation_hours integer not null default 24 check(reservation_hours between 1 and 72),status text not null default 'draft' check(status in ('draft','open','paused','closed')),permit_reference text,created_at timestamptz not null default now());
create table raffle_rules(id uuid primary key default gen_random_uuid(),raffle_id uuid not null references raffles(id),version integer not null,body text not null,published_at timestamptz,unique(raffle_id,version));
create table tickets(id uuid primary key default gen_random_uuid(),raffle_id uuid not null references raffles(id),folio integer not null check(folio>0),state ticket_state not null default 'available',physical_delivered_at timestamptz,unique(raffle_id,folio));
create table ticket_numbers(id uuid primary key default gen_random_uuid(),raffle_id uuid not null references raffles(id),ticket_id uuid not null references tickets(id),number integer not null check(number between 0 and 999),unique(raffle_id,number),unique(ticket_id,number));
create table buyers(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,created_at timestamptz not null default now());
create table orders(id uuid primary key default gen_random_uuid(),raffle_id uuid not null references raffles(id),buyer_id uuid not null references buyers(id),seller_id uuid references profiles(id),source text not null check(source in ('public','seller')),state order_state not null default 'reserved',total_cents integer not null check(total_cents>0),expires_at timestamptz not null,created_at timestamptz not null default now());
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),ticket_id uuid not null references tickets(id),price_cents integer not null check(price_cents>0),released_at timestamptz);
create unique index unique_active_ticket_sale on order_items(ticket_id) where released_at is null;
create table payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),amount_cents integer not null check(amount_cents>0),method text not null check(method in ('transfer','cash')),reference text,state payment_state not null default 'pending',reviewed_by uuid references profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create unique index unique_transfer_reference on payments(reference) where method='transfer' and reference is not null and state <> 'rejected';
create table payment_evidence(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id),storage_path text not null,sha256 text,created_at timestamptz not null default now());
create table ticket_events(id bigint generated always as identity primary key,ticket_id uuid references tickets(id),actor_id uuid,action text not null,details jsonb,created_at timestamptz not null default now());
create table audit_logs(id bigint generated always as identity primary key,actor_id uuid,entity text not null,entity_id uuid,action text not null,details jsonb,created_at timestamptz not null default now());
create table raffle_closures(id uuid primary key default gen_random_uuid(),raffle_id uuid not null references raffles(id),snapshot jsonb not null,created_by uuid references profiles(id),created_at timestamptz not null default now());
-- Block browser access to sensitive tables. Server-side endpoints enforce permissions.
alter table profiles enable row level security;alter table raffles enable row level security;alter table raffle_rules enable row level security;alter table tickets enable row level security;alter table ticket_numbers enable row level security;alter table buyers enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table payments enable row level security;alter table payment_evidence enable row level security;alter table ticket_events enable row level security;alter table audit_logs enable row level security;alter table raffle_closures enable row level security;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-evidence','payment-evidence',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
